function selectScheduleDay(day) {
  state.scheduleDay = Number(day);
  render();
}
function renderMaster() {
  const today = todayIdx(),
    date = todayISO(),
    parity = getWeekParity(date);
  const days = [...(db.activeDays || [0, 1, 2, 3, 4, 5])].sort((a, b) => a - b),
    periods = db.periods || 6;
  const selected = days.includes(state.scheduleDay)
    ? state.scheduleDay
    : days.includes(today)
      ? today
      : days[0];
  const number = (n) => n.toLocaleString("fa-IR");
  let weekly = 0;
  for (const day of days)
    for (let p = 0; p < periods; p++) {
      const e = getMasterEntry(day, p, date);
      if (e && (!state.masterFilter || e.classId === state.masterFilter))
        weekly++;
    }
  const slot = (day, p, compact = false) => {
    const entry = getMasterEntry(day, p, date),
      other =
        entry && state.masterFilter && entry.classId !== state.masterFilter;
    const cls = entry ? findClassById(entry.classId) : null,
      lesson = cls ? getLessonObj(cls.classObj, entry.lessonId) : null;
    const filled = entry && !other && lesson;
    let s =
      '<article class="week-slot ' +
      (filled ? "is-filled" : other ? "is-other" : "is-empty") +
      '">';
    if (!compact)
      s +=
        '<div class="week-period"><span>زنگ</span><strong>' +
        number(p + 1) +
        "</strong></div>";
    s += '<div class="week-slot-content">';
    if (filled) {
      s +=
        `<div class="week-class-label"><span class="week-class-name"><span class="week-color" style="background:${getClassColor(entry.classId)}"></span>${esc(cls.classObj.name)}</span><span class="week-school">${esc(cls.school.name)}</span></div><h4>${esc(lesson.name)}</h4><p>${esc(lesson.teacher || "دبیر تعیین نشده")}</p><div class="week-slot-actions no-print"><button data-legacy-click="schedule-timetable:0" data-legacy-click-arg5="${esc(day)}" data-legacy-click-arg6="${esc(p)}">بازکردن جلسه</button><button class="ghost" data-legacy-click="schedule-timetable:17" data-legacy-click-arg7="${esc(day)}" data-legacy-click-arg8="${esc(p)}" aria-label="تنظیم ` +
        esc(DAYS[day]) +
        " زنگ " +
        (p + 1) +
        '">تنظیم زنگ</button></div>';
    } else if (other) {
      s += `<h4>برنامه کلاس دیگر</h4><p>کلاس انتخاب‌شده در این زنگ برنامه ندارد.</p><button class="ghost no-print" data-legacy-click="schedule-timetable:1" data-legacy-click-arg0="${esc(day)}" data-legacy-click-arg1="${esc(p)}">بررسی برنامه</button>`;
    } else {
      s +=
        "<h4>" +
        (entry ? "درس نیازمند بررسی است" : "زنگ آزاد") +
        "</h4><p>" +
        (entry
          ? "تعریف درس این زنگ در دسترس نیست."
          : "برای این زنگ کلاس و درس انتخاب کنید.") +
        '</p><button class="week-add ghost no-print" data-legacy-click="week-configure" data-configure="' +
        (entry ? "yes" : "no") +
        '" data-day="' +
        day +
        '" data-period="' +
        p +
        '">' +
        EduIcons.html("add") +
        "<span>تنظیم برنامه</span></button>";
    }
    return s + "</div></article>";
  };
  let h = headerHtml();
  h +=
    '<section class="card week-overview" aria-labelledby="weekOverviewTitle"><div class="week-overview-info"><header class="week-overview-title"><span class="week-overview-symbol no-print" aria-hidden="true">' +
    EduIcons.html("calendar-week") +
    '</span><h2 id="weekOverviewTitle">برنامه هفتگی</h2><span class="week-parity ' +
    parity +
    '">هفته ' +
    (parity === "odd" ? "فرد" : "زوج") +
    '</span></header><div class="week-overview-details"><span class="week-overview-date">' +
    EduIcons.html("calendar") +
    '<span>از <time datetime="' +
    esc(getSaturdayOf(date)) +
    '">' +
    esc(faDate(getSaturdayOf(date))) +
    '</time></span></span><span class="week-overview-count"><strong>' +
    number(weekly) +
    '</strong><span>زنگ برنامه‌ریزی‌شده</span></span></div></div><label class="week-filter no-print">نمایش برنامه کلاس<select data-legacy-change="schedule-timetable:3"><option value="">همه کلاس‌ها</option>';
  for (const school of db.schools)
    for (const c of school.classes)
      h +=
        '<option value="' +
        esc(c.id) +
        '" ' +
        (state.masterFilter === c.id ? "selected" : "") +
        ">" +
        esc(school.name) +
        " — " +
        esc(c.name) +
        "</option>";
  h += "</select></label></section>";
  if (!days.length)
    h +=
      '<div class="card empty"><strong>روز کاری انتخاب نشده است</strong><p>از تنظیمات برنامه، روزهای تدریس خود را فعال کنید.</p></div>';
  else {
    h +=
      '<section class="week-agenda"><nav class="week-day-picker no-print" aria-label="انتخاب روز برنامه">';
    for (const d of days)
      h +=
        `<button type="button" aria-pressed="${d === selected}" data-legacy-click="schedule-timetable:4" data-legacy-click-arg1="${esc(d)}"><span>` +
        esc(DAYS[d]) +
        "</span>" +
        (d === today ? "<small>امروز</small>" : "") +
        "</button>";
    const count = Array.from({ length: periods }, (_, p) =>
      getMasterEntry(selected, p, date),
    ).filter(
      (e) => e && (!state.masterFilter || e.classId === state.masterFilter),
    ).length;
    h +=
      '</nav><header class="week-day-heading"><div class="week-day-identity"><span class="week-day-symbol no-print" aria-hidden="true">' +
      EduIcons.html("calendar-week") +
      "</span><h3>" +
      esc(DAYS[selected]) +
      '</h3></div><dl class="week-day-stats" aria-label="خلاصهٔ زنگ‌های روز"><div class="week-day-stat is-scheduled"><dt>دارای برنامه</dt><dd>' +
      number(count) +
      '</dd></div><div class="week-day-stat"><dt>کل زنگ‌ها</dt><dd>' +
      number(periods) +
      '</dd></div></dl></header><div class="week-slot-list">';
    for (let p = 0; p < periods; p++) h += slot(selected, p);
    h += "</div></section>";
  }
  h +=
    '<details class="card week-settings no-print" ' +
    (state.masterSettingsOpen ? "open" : "") +
    ' data-legacy-toggle="week-settings-toggle"><summary><span class="week-settings-heading"><span class="week-settings-symbol" aria-hidden="true">' +
    EduIcons.html("settings") +
    '</span><span class="week-settings-title"><strong>تنظیمات روزها و زنگ‌ها</strong><small>روزهای تدریس، تعداد زنگ‌ها و مبنای هفته</small></span></span></summary><div class="week-settings-body"><section class="week-settings-days"><h4><span class="week-setting-icon" aria-hidden="true">' +
    EduIcons.html("calendar-week") +
    '</span>روزهای کاری</h4><p>روزهای تدریس خود را مشخص کنید.</p><div class="week-working-days">';
  for (const [i, day] of DAYS.entries())
    h +=
      `<label><input type="checkbox" ${days.includes(i) ? "checked" : ""} data-legacy-change="schedule-timetable:5" data-legacy-change-arg1="${esc(i)}"><span>` +
      esc(day) +
      "</span></label>";
  h +=
    `</div></section><section class="week-settings-periods"><h4><span class="week-setting-icon" aria-hidden="true">${EduIcons.html("clock")}</span>تعداد زنگ‌های روزانه</h4><p>تعداد زنگ‌های هر روز را مشخص کنید.</p><div class="week-period-controls"><button class="ghost" data-legacy-click="schedule-timetable:6" aria-label="کاهش تعداد زنگ"><svg class="week-step-icon" width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M4 10h12"/></svg></button><strong>` +
    number(periods) +
    ` زنگ</strong><button class="ghost" data-legacy-click="schedule-timetable:7" aria-label="افزایش تعداد زنگ"><svg class="week-step-icon" width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true" focusable="false"><path d="M4 10h12"/><path d="M10 4v12"/></svg></button></div><p class="week-save-hint">تغییر روزها و تعداد زنگ‌ها خودکار ذخیره می‌شود.</p></section><section class="week-settings-origin"><h4><span class="week-setting-icon" aria-hidden="true">${EduIcons.html("calendar")}</span>مبنای هفته‌های فرد و زوج</h4><p>تاریخ شنبه‌ای را انتخاب کنید که مبنای محاسبه هفته‌ها باشد.</p><div class="week-start-date"><label>تاریخ شروع<input type="date" id="weekStartInput" data-mutating="1" value="` +
    esc(db.settings.weekStartDate || date) +
    `" data-legacy-change="schedule-timetable:8"></label><span class="shamsi-display" id="shamsiWeekStart">` +
    esc(toShamsi(db.settings.weekStartDate || date)) +
    `</span><button data-legacy-click="schedule-timetable:9">ذخیره تاریخ مبنا</button></div></section></div></details>`;
  return h;
}

async function legacy_toggleActiveDay(dayIdx) {
  if (!db.activeDays) db.activeDays = [0, 1, 2, 3, 4, 5];
  const idx = db.activeDays.indexOf(dayIdx);
  if (idx === -1) db.activeDays.push(dayIdx);
  else db.activeDays.splice(idx, 1);
  db.activeDays.sort((a, b) => a - b);
  await saveDB();
  render();
}
async function legacy_saveWeekStartDate() {
  const v = document.getElementById("weekStartInput").value;
  if (!v) return alert("تاریخ را وارد کنید");
  db.settings.weekStartDate = v;
  await saveDB();
  render();
  alert("✅ تاریخ شروع محاسبه ذخیره شد");
}
async function legacy_changePeriods(d) {
  const next = clamp((db.periods || 6) + d, 1, 12);
  const occupied = Object.entries(db.masterSchedule || {}).filter(
    ([key, value]) => value && Number(key.split("-")[1]) >= next,
  );
  if (next < (db.periods || 6) && occupied.length) {
    alert(
      "کاهش تعداد زنگ‌ها انجام نشد؛ ابتدا برنامه زنگ‌های " +
        [...new Set(occupied.map(([key]) => Number(key.split("-")[1]) + 1))]
          .sort((a, b) => a - b)
          .join("، ") +
        " را جابه‌جا یا پاک کنید.",
    );
    return;
  }
  db.periods = next;
  await saveDB();
  render();
}

function openMasterConfig(day, period) {
  const cur = getBothEntries(day, period);
  const allClasses = [];
  db.schools.forEach((s) =>
    s.classes.forEach((c) => allClasses.push({ school: s, class: c })),
  );
  if (!allClasses.length) {
    showModal(
      "تنظیم زنگ",
      `<p class="empty">ابتدا مدرسه و کلاس بسازید</p><button data-legacy-click="schedule-timetable:10">بستن</button>`,
    );
    return;
  }
  function classSelect(id, val) {
    return `<select id="${id}" style="flex:1" data-legacy-change="schedule-timetable:11" data-legacy-change-arg1="${esc(id)}">
      <option value="">— هیچ —</option>
      ${allClasses.map((x) => `<option value="${x.class.id}" ${x.class.id === val ? "selected" : ""}>${esc(x.school.name)} / ${esc(x.class.name)}</option>`).join("")}
    </select>`;
  }
  function lessonSelect(id, classId, lessonId) {
    if (!classId)
      return `<select id="${id}" style="flex:1"><option value="">— اول کلاس —</option></select>`;
    const cls = findClassById(classId);
    if (!cls)
      return `<select id="${id}" style="flex:1"><option value="">— خطا —</option></select>`;
    return `<select id="${id}" style="flex:1">
      <option value="">— درس —</option>
      ${(cls.classObj.lessons || []).map((l) => `<option value="${l.id}" ${l.id === lessonId ? "selected" : ""}>${esc(l.name)}</option>`).join("")}
    </select>`;
  }

  let h =
    '<div class="week-config-intro"><strong>' +
    esc(DAYS[day]) +
    " · زنگ " +
    (period + 1).toLocaleString("fa-IR") +
    '</strong><p>برنامه ثابت را انتخاب کنید؛ اگر درس هفته‌های فرد و زوج متفاوت است، استثناها را هم مشخص کنید.</p></div><section class="week-config-section"><h4>برنامه ثابت همه هفته‌ها</h4><label for="cfgAllClass">کلاس</label>' +
    classSelect("cfgAllClass", cur.all?.classId) +
    '<label for="cfgAllLesson">درس</label>' +
    lessonSelect("cfgAllLesson", cur.all?.classId, cur.all?.lessonId) +
    "</section>";
  h += `<details class="week-config-exceptions" ${cur.odd || cur.even ? "open" : ""}><summary>برنامه متفاوت برای هفته فرد یا زوج</summary><section class="week-config-section"><h4>هفته‌های فرد</h4><label for="cfgOddClass">کلاس</label>${classSelect("cfgOddClass", cur.odd?.classId)}<label for="cfgOddLesson">درس</label>${lessonSelect("cfgOddLesson", cur.odd?.classId, cur.odd?.lessonId)}</section><section class="week-config-section"><h4>هفته‌های زوج</h4><label for="cfgEvenClass">کلاس</label>${classSelect("cfgEvenClass", cur.even?.classId)}<label for="cfgEvenLesson">درس</label>${lessonSelect("cfgEvenLesson", cur.even?.classId, cur.even?.lessonId)}</section></details><p class="week-config-note">برنامه فرد یا زوج، در همان هفته جایگزین برنامه ثابت می‌شود. نام دبیر از مشخصات درس خوانده می‌شود.</p><div class="week-config-actions"><button data-legacy-click="schedule-timetable:18" data-legacy-click-arg5="${esc(day)}" data-legacy-click-arg6="${esc(period)}">ذخیره برنامه</button><button class="ghost" data-legacy-click="schedule-timetable:12">انصراف</button><button class="danger" data-legacy-click="schedule-timetable:19" data-legacy-click-arg7="${esc(day)}" data-legacy-click-arg8="${esc(period)}">پاک‌کردن این زنگ</button></div>`;

  showModal(`تنظیم ${DAYS[day]} — زنگ ${period + 1}`, h);
}

function updateLessonOptions(classSelectId) {
  const classId = document.getElementById(classSelectId).value;
  const lessonSelectId = classSelectId.replace("Class", "Lesson");
  const sel = document.getElementById(lessonSelectId);
  if (!sel) return;
  if (!classId) {
    sel.innerHTML = '<option value="">— اول کلاس —</option>';
    return;
  }
  const cls = findClassById(classId);
  if (!cls) {
    sel.innerHTML = '<option value="">— خطا —</option>';
    return;
  }
  sel.innerHTML =
    '<option value="">— درس —</option>' +
    (cls.classObj.lessons || [])
      .map((l) => `<option value="${l.id}">${esc(l.name)}</option>`)
      .join("");
}

async function legacy_saveMasterConfig(day, period) {
  db.masterSchedule = db.masterSchedule || {};
  const map = {
    all: { c: "cfgAllClass", l: "cfgAllLesson" },
    odd: { c: "cfgOddClass", l: "cfgOddLesson" },
    even: { c: "cfgEvenClass", l: "cfgEvenLesson" },
  };
  Object.keys(map).forEach((k) => {
    const classId = document.getElementById(map[k].c).value;
    const lessonId = document.getElementById(map[k].l).value;
    const key = `${day}-${period}-${k}`;
    if (classId && lessonId) {
      const cls = findClassById(classId);
      if (cls)
        db.masterSchedule[key] = {
          schoolId: cls.school.id,
          classId,
          lessonId,
        };
    } else {
      delete db.masterSchedule[key];
    }
  });
  await saveDB();
  closeModal();
  render();
}

async function legacy_clearMasterConfig(day, period) {
  if (!confirm("کل تنظیمات این زنگ پاک شوند؟")) return;
  delete db.masterSchedule[`${day}-${period}-all`];
  delete db.masterSchedule[`${day}-${period}-odd`];
  delete db.masterSchedule[`${day}-${period}-even`];
  await saveDB();
  closeModal();
  render();
}

function legacy_clickMasterCell(day, period) {
  const entry = getMasterEntry(day, period, todayISO());
  if (!entry || !entry.lessonId) {
    openMasterConfig(day, period);
    return;
  }
  const cls = findClassById(entry.classId);
  if (!cls) {
    alert("کلاس/درس حذف شده. لطفاً مجدد تنظیم کنید");
    openMasterConfig(day, period);
    return;
  }

  const allClasses = [];
  db.schools.forEach((s) =>
    s.classes.forEach((c) => allClasses.push({ school: s, class: c })),
  );

  const existing = db.sessions
    .filter((s) => {
      const sd = getDayIdxFromDate(s.date);
      return s.classId === entry.classId && s.period === period && sd === day;
    })
    .sort((a, b) => b.date.localeCompare(a.date));

  let h = `<header class="session-setup-heading">
    <span class="session-setup-symbol" aria-hidden="true">${EduIcons.html("calendar")}</span>
    <div><span class="session-setup-eyebrow">برنامه هفتگی</span><h4>${esc(DAYS[day])} · زنگ ${(period + 1).toLocaleString("fa-IR")}</h4><p>کلاس، درس و تاریخ جلسه را بررسی کنید.</p></div>
  </header>
  <div class="session-setup-grid">
    <label class="session-field session-field-wide" for="sessNewClass"><span>کلاس</span>
      <select id="sessNewClass" data-legacy-change="schedule-timetable:13">
        ${allClasses.map((x) => `<option value="${x.class.id}" ${x.class.id === entry.classId ? "selected" : ""}>${esc(x.school.name)} / ${esc(x.class.name)}</option>`).join("")}
      </select>
    </label>
    <label class="session-field session-field-wide" for="sessNewLesson"><span>درس</span>
      <select id="sessNewLesson">
        ${(cls.classObj.lessons || []).map((l) => `<option value="${l.id}" ${l.id === entry.lessonId ? "selected" : ""}>${esc(l.name)}</option>`).join("")}
      </select>
    </label>
    <label class="session-field" for="sessNewDate"><span>تاریخ جلسه</span>
      <input type="date" id="sessNewDate" data-session-calendar="master" value="${todayISO()}" data-legacy-change="schedule-timetable:14">
      <span class="shamsi-display" id="shamsiSessNew">${toShamsi(todayISO())}</span>
    </label>
  </div>
  <p class="session-setup-help">در همین تاریخ و زنگ، جلسهٔ ثبت‌شدهٔ همین درس ادامه پیدا می‌کند؛ تداخل با جلسهٔ دیگر اجازهٔ ثبت نمی‌دهد.</p>
  <div class="session-setup-actions">
    <button type="button" data-legacy-click="schedule-timetable:15" data-legacy-click-arg6="${esc(day)}" data-legacy-click-arg7="${esc(period)}">${EduIcons.html("arrow")}<span>شروع / ادامه جلسه</span></button>
  </div>`;

  if (existing.length) {
    h += `<section class="session-setup-history"><header><h4>جلسات قبلی این زنگ</h4><span>${existing.length.toLocaleString("fa-IR")} جلسه</span></header><div class="session-setup-recent">`;
    existing.slice(0, 15).forEach((s) => {
      const present = Object.values(s.attendance).filter(
        (x) =>
          x === "present" || (typeof x === "string" && x.startsWith("late")),
      ).length;
      const total = sessionStudents(cls.classObj, s).length;
      const lessonName = cls.classObj.lessons.find(
        (l) => l.id === s.lessonId,
      )?.name;
      h += `<button type="button" class="session-setup-recent-item" data-legacy-click="schedule-timetable:16" data-legacy-click-arg0="${esc(s.id)}">
        <span class="session-setup-recent-copy"><strong>${esc(faDate(s.date))}</strong>${lessonName ? `<span>${esc(lessonName)}</span>` : ""}<small>${present}/${total} حاضر · ${s.scores.length} امتیاز</small></span>
        <span class="session-setup-recent-arrow" aria-hidden="true">${EduIcons.html("arrow")}</span>
      </button>`;
    });
    h += `</div></section>`;
  }
  showModal(
    "ثبت جلسه",
    `<div class="session-start-panel" data-session-day="${esc(day)}" data-session-period="${esc(period)}">` +
      h +
      "</div>",
  );
}

function updateSessionLessonOptions() {
  const classId = document.getElementById("sessNewClass").value;
  const sel = document.getElementById("sessNewLesson");
  if (!sel) return;
  const cls = findClassById(classId);
  if (!cls) {
    sel.innerHTML = '<option value="">ابتدا کلاس را انتخاب کنید</option>';
    return;
  }
  sel.innerHTML = (cls.classObj.lessons || [])
    .map((l) => `<option value="${l.id}">${esc(l.name)}</option>`)
    .join("");
}

async function legacy_startSessionFromMaster(day, period) {
  const date = document.getElementById("sessNewDate").value;
  const classId = document.getElementById("sessNewClass").value;
  const lessonId = document.getElementById("sessNewLesson").value;

  if (!date) return alert("تاریخ را انتخاب کنید");
  if (!classId || !lessonId) return alert("کلاس و درس را انتخاب کنید");

  const dIdx = getDayIdxFromDate(date);
  if (dIdx !== day) {
    if (
      !confirm(
        `تاریخ ${faDate(date)} روز ${DAYS[dIdx]} است، نه ${DAYS[day]}. ادامه می‌دهید؟`,
      )
    )
      return;
  }

  let session = db.sessions.find(
    (s) => s.classId === classId && s.date === date && s.period === period,
  );
  if (!session) {
    const cls = findClassById(classId);
    session = {
      id: uid(),
      schoolId: cls.school.id,
      classId: classId,
      date,
      period,
      lessonId: lessonId,
      poudmanId: null,
      unitId: null,
      attendance: {},
      scores: [],
      roster: snapshotRoster(cls.classObj),
    };
    db.sessions.push(session);
    await saveDB({ sessionId: session.id });
  } else if (session.lessonId !== lessonId) {
    alert(
      "این زنگ برای درس دیگری ثبت شده است؛ برای حفظ سابقه جلسه قبلی باز می‌شود.",
    );
  }
  openSessionModal(session);
}
function openExistingSession(id) {
  const sess = db.sessions.find((s) => s.id === id);
  if (sess) openSessionModal(sess);
}
